cd /workspace && cat > /tmp/mapblock.php <<'EOF'
<?php
$blocks = \Drupal::entityTypeManager()->getStorage('block')->loadByProperties(['theme'=>'opcult']);
foreach ($blocks as $b) {
  $p = $b->getPluginId();
  if (str_contains($p,'map') || str_contains($p,'location')) echo $b->id() . " => $p (" . $b->getRegion() . ")\n";
}
echo "--- any leaflet view blocks ---\n";
foreach ($blocks as $b) { $p=$b->getPluginId(); if (str_contains($p,'leaflet')) echo $b->id()." => $p\n"; }
EOF
cp /tmp/mapblock.php /workspace/mapblock_tmp.php && su ddevuser -c "ddev drush php:script mapblock_tmp.php" 2>&1 | tail -10; rm -f /workspace/mapblock_tmp.php
